/* Generated by Goose Zero-GC C11 Backend for FipSOs v5.5 */
#include "fipsos_rt.h"
#include "simd_nn_rt.h"
#include "fnn2_dyn.h"
#include "simd_seq_nn.h"

static void ai_write_str(const char* s) {
    size_t n = 0;
    while (s[n] != '\0') ++n;
    if (n > 0) (void)fipsos_sc3(FIPSOS_SYS_WRITE, 1L, (long)s, (long)n);
}

static void ai_write_i64(int64_t v) {
    char buf[32], out[32];
    int idx = 0;
    if (v < 0) { ai_write_str("-"); v = (v == INT64_MIN) ? INT64_MAX : -v; }
    if (v == 0) { ai_write_str("0"); return; }
    while (v > 0 && idx < 30) { buf[idx++] = (char)('0' + (v % 10)); v /= 10; }
    for (int i = 0; i < idx; ++i) out[i] = buf[idx - 1 - i];
    (void)fipsos_sc3(FIPSOS_SYS_WRITE, 1L, (long)out, (long)idx);
}

static int ai_streq(const char* a, const char* b) {
    size_t i = 0;
    while (a[i] && b[i]) { if (a[i] != b[i]) return 0; ++i; }
    return a[i] == b[i];
}

static int64_t ai_atoi(const char* s) {
    int64_t v = 0;
    for (size_t i = 0; s[i] >= '0' && s[i] <= '9'; ++i) v = v * 10 + (s[i] - '0');
    return v;
}

static const char* ai_class_name(int64_t cls) {
    return (cls == 0) ? "IDLE" : (cls == 1) ? "BALANCED" : "HIGH_LOAD";
}

static const char* ai_guard_name(int64_t cls) {
    return (cls == 0) ? "SAFE" : (cls == 1) ? "SUSPICIOUS" : "INTRUSION";
}

static int64_t ai_parse_kv(const char* buf, const char* key, int64_t fallback) {
    size_t klen = 0;
    while (key[klen] != '\0') ++klen;
    for (size_t i = 0; buf[i] != '\0'; ++i) {
        size_t j = 0;
        while (j < klen && buf[i + j] == key[j]) ++j;
        if (j == klen && (buf[i + j] == '=' || buf[i + j] == ':')) {
            size_t p = i + j + 1;
            while (buf[p] == ' ') ++p;
            if (buf[p] >= '0' && buf[p] <= '9') return ai_atoi(buf + p);
        }
    }
    return fallback;
}

static int ai_read_telemetry(int64_t* cpu, int64_t* mem, int64_t* procs, int64_t* io_kb) {
    fipsos_sysinfo_t si;
    int got_real = 0;
    *cpu = 0; *mem = 0; *procs = 0; *io_kb = 0;
    if (fipsos_sc1(FIPSOS_SYS_SYSINFO, (long)&si) == 0) {
        if (si.procs > 0) *procs = (int64_t)si.procs;
        if (si.totalram > 0) {
            uint64_t used = (si.totalram > si.freeram) ? (si.totalram - si.freeram) : 0;
            *mem = (int64_t)((used * 100ULL) / si.totalram);
        }
        got_real = 1;
    }
    int fd = open("/sys/fipsos/hwmon", O_RDONLY);
    if (fd < 0) return got_real ? 0 : -1;
    char buf[512];
    ssize_t n = read(fd, buf, sizeof(buf) - 1);
    close(fd);
    if (n <= 0) return got_real ? 0 : -1;
    buf[n] = '\0';
    *cpu = ai_parse_kv(buf, "Core 0", ai_parse_kv(buf, "cpu", *cpu));
    *mem = ai_parse_kv(buf, "mem", *mem);
    *procs = ai_parse_kv(buf, "procs", *procs);
    *io_kb = ai_parse_kv(buf, "io", *io_kb);
    return 0;
}

static void ai_print_result(const char* mode, const char* label, int64_t us) {
    ai_write_str(mode); ai_write_str(": class="); ai_write_str(label);
    ai_write_str(" probs=["); ai_write_i64(fnn_prob_pct(0));
    ai_write_str("%,"); ai_write_i64(fnn_prob_pct(1));
    ai_write_str("%,"); ai_write_i64(fnn_prob_pct(2));
    ai_write_str("%] latency="); ai_write_i64(us); ai_write_str("us\n");
}

static int run_guard(int argc, char** argv) {
    int64_t rate = (argc > 2) ? ai_atoi(argv[2]) : 8;
    int64_t trav = (argc > 3) ? ai_atoi(argv[3]) : 0;
    int64_t e403 = (argc > 4) ? ai_atoi(argv[4]) : 0;
    int64_t sock = (argc > 5) ? ai_atoi(argv[5]) : 2;
    int64_t outw = (argc > 6) ? ai_atoi(argv[6]) : 0;
    int64_t slot = (argc > 7) ? ai_atoi(argv[7]) : 20;
    int64_t cls = fnn_guard_infer(rate, trav, e403, sock, outw, slot);
    ai_write_str("[fips_ai --guard] backend="); ai_write_str(fnn_simd_backend());
    ai_write_str(" verdict="); ai_write_str(ai_guard_name(cls));
    ai_write_str("\n");
    ai_print_result("guard_nn", ai_guard_name(cls), fnn_last_us());
    if (cls == 2) {
        int lfd = open("/mnt/fat0/security_ai.log", O_WRONLY | O_CREAT | O_APPEND, 0644);
        if (lfd >= 0) {
            const char msg[] = "[AI_GUARD] /bin/fips_ai --guard: INTRUSION -> AUTO_SANDBOX\n";
            (void)fipsos_sc3(FIPSOS_SYS_WRITE, (long)lfd, (long)msg, (long)(sizeof(msg) - 1));
            close(lfd);
        }
        (void)fipsos_sc2(450L /* SYS_FIPS_SANDBOX */, 0x05L /* CAP_FS_READ | CAP_NET */, 0L);
        ai_write_str("action=AUTO_SANDBOX\n");
    }
    return 0;
}

static float ai_atof(const char* s, const char** next_out) {
    float sign = 1.0f, val = 0.0f, scale = 0.1f;
    if (*s == '-') { sign = -1.0f; ++s; }
    else if (*s == '+') { ++s; }
    while (*s >= '0' && *s <= '9') { val = val * 10.0f + (float)(*s - '0'); ++s; }
    if (*s == '.') {
        ++s;
        while (*s >= '0' && *s <= '9') { val += (float)(*s - '0') * scale; scale *= 0.1f; ++s; }
    }
    if (next_out) *next_out = s;
    return sign * val;
}

static int run_model_fnn2(int argc, char** argv) {
    const char* model_path = "/mnt/fat0/custom_model.fnn";
    const char* input_csv = "0.5,0.5,0.5,0.5";
    for (int i = 1; i + 1 < argc; ++i) {
        if (ai_streq(argv[i], "--model")) model_path = argv[i + 1];
        else if (ai_streq(argv[i], "--input")) input_csv = argv[i + 1];
    }
    static Fnn2Model m;
    if (!fnn2_load(model_path, &m)) {
        ai_write_str("[fips_ai --model] error: no se pudo cargar FNN2 ");
        ai_write_str(model_path); ai_write_str("\n");
        return 1;
    }
    float inputs[FNN2_MAX_IN] = {0};
    int n_in = 0;
    const char* p = input_csv;
    while (*p != '\0' && n_in < FNN2_MAX_IN) {
        const char* nxt = p;
        inputs[n_in++] = ai_atof(p, &nxt);
        p = (*nxt == ',') ? (nxt + 1) : nxt;
        if (*nxt != ',') break;
    }
    int best = fnn2_infer(&m, inputs, n_in);
    ai_write_str("[fips_ai --model] backend="); ai_write_str(fnn_simd_backend());
    ai_write_str(" format=FNN2 dims="); ai_write_i64((int64_t)m.hdr.in_dim);
    ai_write_str("x"); ai_write_i64((int64_t)m.hdr.hid_dim);
    ai_write_str("x"); ai_write_i64((int64_t)m.hdr.out_dim); ai_write_str("\n");
    ai_write_str("fnn2_simd: class="); ai_write_i64((int64_t)best);
    ai_write_str(" probs=[");
    for (uint32_t i = 0; i < m.hdr.out_dim; ++i) {
        if (i > 0) ai_write_str(",");
        ai_write_i64((int64_t)(m.probs[i] * 100.0f + 0.5f));
        ai_write_str("%");
    }
    ai_write_str("] latency="); ai_write_i64(m.last_us); ai_write_str("us\n");
    return 0;
}

static int run_audio_listen(void) {
    uint8_t pcm[256];
    int fd = open("/dev/audio", O_RDONLY);
    if (fd < 0) { ai_write_str("[fips_ai] ERROR: no se pudo abrir /dev/audio\n"); return 1; }
    ssize_t n = read(fd, pcm, sizeof(pcm));
    close(fd);
    if (n <= 0) { ai_write_str("[fips_ai] ERROR: lectura PCM vacia en /dev/audio\n"); return 1; }
    uint64_t sum_sq = 0;
    int64_t zcr = 0;
    int prev_hi = (pcm[0] >= 128);
    for (ssize_t i = 0; i < n; ++i) {
        int diff = (int)pcm[i] - 128;
        sum_sq += (uint64_t)(diff * diff);
        int hi = (pcm[i] >= 128);
        if (i > 0 && hi != prev_hi) { zcr++; prev_hi = hi; }
    }
    int64_t mean_sq = (int64_t)(sum_sq / (uint64_t)n);
    int64_t energy_pct = (mean_sq * 100) / (48 * 48);
    if (energy_pct > 100) energy_pct = 100;
    fnn_load_model("/mnt/fat0/model.fnn");
    fnn_set_quantized(0);
    int64_t cls = fnn_run_telemetry(energy_pct, 50, zcr, 16);
    ai_write_str("[fips_ai] --audio-listen /dev/audio (");
    ai_write_i64((int64_t)n);
    ai_write_str("B PCM) | energy="); ai_write_i64(energy_pct);
    ai_write_str("% zcr="); ai_write_i64(zcr);
    ai_write_str(" | class="); ai_write_str(ai_class_name(cls));
    ai_write_str(" backend="); ai_write_str(fnn_simd_backend());
    ai_write_str(" latency="); ai_write_i64(fnn_last_us()); ai_write_str("us\n");
    return 0;
}

static int run_stream_audit(void) {
    uint8_t pcm[256];
    int fd = open("/dev/audio", O_RDONLY);
    if (fd < 0) { ai_write_str("[fips_ai --stream-audit] ERROR: /dev/audio no disponible (-ENODEV)\n"); return 1; }
    ssize_t n = read(fd, pcm, sizeof(pcm));
    close(fd);
    if (n < 4) { ai_write_str("[fips_ai --stream-audit] ERROR: captura DMA vacia o -ENODEV\n"); return 1; }
    /* HDA ISD0 captura 48 kHz, 16-bit signed PCM estereo (4 bytes/frame) */
    ssize_t frames = n / 4;
    uint64_t sum_sq = 0;
    int64_t zcr = 0;
    int16_t s0 = (int16_t)((uint16_t)pcm[0] | ((uint16_t)pcm[1] << 8));
    int prev_hi = (s0 >= 0);
    for (ssize_t f = 0; f < frames; ++f) {
        ssize_t off = f * 4;
        int32_t s = (int16_t)((uint16_t)pcm[off] | ((uint16_t)pcm[off + 1] << 8));
        sum_sq += (uint64_t)((int64_t)s * (int64_t)s);
        int hi = (s >= 0);
        if (f > 0 && hi != prev_hi) { zcr++; prev_hi = hi; }
    }
    uint64_t mean_sq = sum_sq / (uint64_t)frames;
    int64_t energy_pct = (int64_t)((mean_sq * 100ULL) / (16384ULL * 16384ULL));
    if (energy_pct > 100) energy_pct = 100;
    int64_t dom_hz = (zcr * 48000) / (2 * (int64_t)frames);

    int64_t cpu = 0, mem = 0, procs = 0, io_kb = 0;
    if (ai_read_telemetry(&cpu, &mem, &procs, &io_kb) != 0) {
        ai_write_str("[fips_ai --stream-audit] ERROR: sin telemetria real en /sys/fipsos/hwmon\n");
        return 1;
    }

    fnn_load_model("/mnt/fat0/model.fnn");
    fnn_set_quantized(0);
    int64_t cls = fnn_run_telemetry(cpu + (energy_pct / 4), mem, procs + zcr, io_kb);
    ai_write_str("[fips_ai] --stream-audit | pcm="); ai_write_i64((int64_t)n);
    ai_write_str("B energy="); ai_write_i64(energy_pct);
    ai_write_str("% freq="); ai_write_i64(dom_hz);
    ai_write_str("Hz | hwmon cpu="); ai_write_i64(cpu);
    ai_write_str("% mem="); ai_write_i64(mem);
    ai_write_str("% | class="); ai_write_str(ai_class_name(cls));
    ai_write_str(" backend="); ai_write_str(fnn_simd_backend());
    ai_write_str(" latency="); ai_write_i64(fnn_last_us()); ai_write_str("us\n");
    return 0;
}

static int run_seq_infer(int argc, char** argv) {
    const char* model_path = "/mnt/fat0/seq_model.fnn";
    const char* tokens_csv = "1,2,3";
    for (int i = 1; i + 1 < argc; ++i) {
        if (ai_streq(argv[i], "--model")) model_path = argv[i + 1];
        else if (ai_streq(argv[i], "--tokens")) tokens_csv = argv[i + 1];
    }
    static Fnn2Model m;
    if (!fnn2_load(model_path, &m)) {
        ai_write_str("[fips_ai --seq-infer] ERROR: modelo FNN2 no encontrado ");
        ai_write_str(model_path); ai_write_str("\n");
        return 1;
    }
    int tokens[SEQ_MAX_TOKENS];
    int n_tok = 0;
    const char* p = tokens_csv;
    while (*p != '\0' && n_tok < SEQ_MAX_TOKENS) {
        tokens[n_tok++] = (int)ai_atoi(p);
        while (*p != '\0' && *p != ',') ++p;
        if (*p == ',') ++p;
    }
    if (n_tok <= 0) {
        ai_write_str("[fips_ai --seq-infer] ERROR: lista de tokens vacia\n");
        return 1;
    }
    static SeqNnResult res;
    if (seq_nn_infer(&m, tokens, n_tok, &res) != 0) {
        ai_write_str("[fips_ai --seq-infer] ERROR: fallo en motor GRU\n");
        return 1;
    }
    ai_write_str("[fips_ai] --seq-infer | backend="); ai_write_str(fnn_simd_backend());
    ai_write_str(" tokens="); ai_write_i64(n_tok);
    ai_write_str(" | hidden=[");
    uint32_t h_show = (res.hid_dim < 4) ? res.hid_dim : 4;
    for (uint32_t i = 0; i < h_show; ++i) {
        if (i > 0) ai_write_str(",");
        ai_write_i64((int64_t)(res.hidden[i] * 100.0f));
    }
    ai_write_str("] | top3=[");
    int k_show = (res.out_dim < 3) ? (int)res.out_dim : 3;
    for (int k = 0; k < k_show; ++k) {
        if (k > 0) ai_write_str(",");
        ai_write_i64(res.top_idx[k]);
        ai_write_str(":");
        ai_write_i64((int64_t)(res.top_prob[k] * 100.0f + 0.5f));
        ai_write_str("%");
    }
    ai_write_str("] latency="); ai_write_i64(res.last_us); ai_write_str("us\n");
    return 0;
}

int main(int argc, char** argv) {
    if (argc >= 2 && ai_streq(argv[1], "--guard")) return run_guard(argc, argv);
    if (argc >= 2 && ai_streq(argv[1], "--audio-listen")) return run_audio_listen();
    if (argc >= 2 && ai_streq(argv[1], "--stream-audit")) return run_stream_audit();
    if (argc >= 2 && ai_streq(argv[1], "--seq-infer")) return run_seq_infer(argc, argv);
    if (argc >= 2 && (ai_streq(argv[1], "--model") || ai_streq(argv[1], "--input"))) return run_model_fnn2(argc, argv);
    int64_t from_file = fnn_load_model("/mnt/fat0/model.fnn");
    int64_t cpu = 0, mem = 0, procs = 0, io_kb = 0;
    ai_read_telemetry(&cpu, &mem, &procs, &io_kb);

    ai_write_str("[fips_ai] Goose Zero-GC + "); ai_write_str(fnn_simd_backend());
    ai_write_str(" MLP (FipSOs v5.4)\n");
    ai_write_str(from_file ? "weights=/mnt/fat0/model.fnn\n" : "weights=builtin_default\n");
    ai_write_str("input: cpu="); ai_write_i64(cpu);
    ai_write_str("% mem="); ai_write_i64(mem);
    ai_write_str("% procs="); ai_write_i64(procs);
    ai_write_str(" io="); ai_write_i64(io_kb); ai_write_str("KB\n");

    fnn_load_model("/mnt/fat0/model.fnn");
    fnn_set_quantized(0);
    int64_t cls_fp32 = fnn_run_telemetry(cpu, mem, procs, io_kb);
    ai_print_result("fp32_simd", ai_class_name(cls_fp32), fnn_last_us());
    fnn_set_quantized(1);
    int64_t cls_int8 = fnn_run_telemetry(cpu, mem, procs, io_kb);
    ai_print_result("int8_sse2", ai_class_name(cls_int8), fnn_last_us());
    return 0;
}
